#!/usr/bin/env python3
"""Create *unverified* human-review candidates from the original OpenDART snapshot.

The hints below are lexicographic document-navigation aids, NOT the frozen E08D
retrieval system and never Gold labels. Sealed holdout questions are not read.
"""
from __future__ import annotations

import argparse
import csv
import gzip
import hashlib
import json
from pathlib import Path

# Hints are deliberately author-specified, not generated by the evaluated retrieval model.
# For multi-evidence items, groups point to distinct concepts that should both be checked.
HINTS = {
    "E09-17": [("재고자산", "단위원가", "평균법", "원가")],
    "E09-18": [("재고자산", "평가손실", "환입", "순실현가능가치")],
    "E09-19": [("무형자산", "상각", "사용가능", "개시")],
    "E09-20": [("연구개발", "개발비", "인식", "무형자산")],
    "E09-21": [("충당부채", "현재가치", "할인", "측정")],
    "E09-22": [("사용권자산", "리스", "감가상각", "후속")],
    "E09-25": [("상각후원가", "유효이자율", "측정", "금융자산")],
    "E09-26": [("기타포괄손익", "공정가치", "사업모형", "계약상")],
    "E09-27": [("당기손익", "공정가치", "금융자산", "손익")],
    "E09-28": [("기대신용손실", "손실충당금", "미래", "신용")],
    "E09-29": [("매출채권", "손실충당금", "간편법", "기대신용손실")],
    "E09-30": [("공정가치 서열", "수준", "관측가능", "평가기법")],
    "E09-33": [("재고자산", "순실현가능가치", "원가"), ("재고자산", "회계추정", "평가손실", "불확실")],
    "E09-34": [("신용위험", "관리", "금융기관"), ("손실충당금", "기대신용손실", "미래")],
    "E09-35": [("유동성위험", "Cash Pooling", "관리"), ("만기분석", "계약상", "현금흐름")],
    "E09-36": [("유형자산", "내용연수", "감가상각"), ("유형자산", "손상", "회수가능")],
    "E09-37": [("금융자산", "사업모형", "분류", "측정"), ("범주별 금융상품", "금융자산", "백만원")],
    "E09-38": [("수익인식", "통제", "수행의무"), ("반품", "환불부채", "추정")],
    "E09-41": [("판매량", "전망", "제품")],
    "E09-42": [("판매목표", "다음 분기", "내부")],
    "E09-43": [("급여명세", "개인", "임직원")],
    "E09-44": [("미래", "주가", "종가")],
    "E09-45": [("별도재무제표", "연결재무제표", "재무상태표")],
    "E09-46": [("협력업체", "계약조건", "거래")],
}


def score(chunk: dict, hints: tuple[str, ...]) -> float:
    text = chunk['quote'].lower()
    section = chunk.get('section', '').lower()
    return sum((3.0 if word.lower() in section else 0.0) +
               (1.0 if word.lower() in text else 0.0) for word in hints)


def select_candidates(chunks: list[dict], groups: list[tuple[str, ...]], limit: int) -> list[tuple[dict, float, str]]:
    # Round-robin at most 3 candidates for each independent evidence concept.
    chosen: dict[str, tuple[dict, float, str]] = {}
    for ix, group in enumerate(groups, 1):
        ranked = sorted(((score(c, group), c) for c in chunks), key=lambda z:(-z[0], z[1]['id']))
        taken = 0
        for value, chunk in ranked:
            if value <= 0: break
            if chunk['id'] in chosen: continue
            chosen[chunk['id']] = (chunk, value, f'concept_{ix}')
            taken += 1
            if taken >= 3: break
    all_words = tuple(dict.fromkeys(word for group in groups for word in group))
    ranked_all = sorted(((score(c, all_words), c) for c in chunks), key=lambda z:(-z[0], z[1]['id']))
    for value, chunk in ranked_all:
        if len(chosen) >= limit or value <= 0: break
        if chunk['id'] not in chosen:
            chosen[chunk['id']] = (chunk, value, 'all_concepts')
    return sorted(chosen.values(), key=lambda item:(-item[1], item[0]['id']))[:limit]


def make_rows(gold_rows: list[dict], chunks: list[dict], limit: int = 12) -> list[dict]:
    out = []
    allowed = {'note_qa', 'multi_evidence', 'abstention'}
    for q in gold_rows:
        if q['split'] != 'new_eval' or q['qa_scope'] not in allowed: continue
        if '{' in q['question']:
            raise ValueError(f"{q['question_id']} has an unfilled template in question")
        groups = HINTS.get(q['question_id'])
        if not groups:
            raise ValueError(f"No independent navigation hints for {q['question_id']}")
        for rank, (chunk, hintscore, group) in enumerate(select_candidates(chunks, groups, limit), 1):
            out.append({
                'question_id': q['question_id'], 'qa_scope': q['qa_scope'],
                'question': q['question'], 'candidate_rank': rank,
                'concept': group, 'hint_score': hintscore,
                'chunk_id': chunk['id'], 'source_id': chunk['source_id'],
                'section': chunk['section'], 'basis_context': chunk['basis_context'],
                'start': chunk['start'], 'end': chunk['end'],
                'quote_sha256': hashlib.sha256(chunk['quote'].encode('utf-8')).hexdigest(),
                'source_url': chunk.get('url') or q.get('source_url') or '',
                'quote': chunk['quote'], 'review_note': '',
            })
    return out


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--gold', type=Path, required=True)
    parser.add_argument('--snapshot', type=Path, required=True)
    parser.add_argument('--out', type=Path, required=True)
    parser.add_argument('--limit', type=int, default=12)
    args = parser.parse_args()
    if args.out.exists(): parser.error('Output already exists: choose a new filename to preserve reviews')
    if not 4 <= args.limit <= 24: parser.error('limit must be in [4,24]')
    from fea.retrieval import structured_chunks
    with gzip.open(args.snapshot, 'rt', encoding='utf-8') as stream:
        snapshot = json.load(stream)
    docs = snapshot['documents']
    docs_by_id = {d['id']:d for d in docs}
    chunks = []
    for doc in docs:
        for c in structured_chunks(doc):
            if c['basis_context'] != 'CFS': continue
            if docs_by_id[c['source_id']]['text'][c['start']:c['end']] != c['quote']:
                raise ValueError('Source text/offset mismatch: ' + c['id'])
            chunks.append(c)
    with args.gold.open(encoding='utf-8-sig', newline='') as stream:
        gold = list(csv.DictReader(stream))
    rows = make_rows(gold, chunks, args.limit)
    if not rows: raise ValueError('No new_eval note/abstention questions. Check --gold CSV')
    args.out.parent.mkdir(parents=True,exist_ok=True)
    with args.out.open('w', encoding='utf-8-sig', newline='') as stream:
        writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
        writer.writeheader(); writer.writerows(rows)
    print(f'Documents={len(docs)}, CFS chunks={len(chunks)}')
    print(f'Question count={len(set(r["question_id"] for r in rows))}, candidate rows={len(rows)}')
    print(f'Created: {args.out}')
    print('CANDIDATES ONLY: exact source/offset/hash checked, no Gold or answer correctness verified.')
    print('Do NOT open sealed_holdout or use these hints to tune the frozen E08-D model.')


if __name__ == '__main__': main()
